39	// Helper: count operations recorded by hookPathFinding-style setter
40	function countOperations(grid, finder, sx, sy, ex, ey) {
41	    var ops = [];
42	    var origProto = Object.getPrototypeOf(grid.getNodeAt(0, 0));
43	
44	    // Clone grid to avoid mutation
45	    var g = grid.clone();
46	
47	    // Hook opened/closed setters on all nodes
48	    for (var r = 0; r < g.height; r++) {
49	        for (var c = 0; c < g.width; c++) {
50	            var node = g.getNodeAt(c, r);
51	            (function(n) {
52	                var _opened = false;
53	                var _closed = false;
54	                Object.defineProperty(n, 'opened', {
55	                    get: function() { return _opened; },
56	                    set: function(v) {
57	                        _opened = v;
58	                        if (v) ops.push({ x: n.x, y: n.y, attr: 'opened' });
59	                    },
60	                    configurable: true
61	                });
62	                Object.defineProperty(n, 'closed', {
63	                    get: function() { return _closed; },
64	                    set: function(v) {
65	                        _closed = v;
66	                        if (v) ops.push({ x: n.x, y: n.y, attr: 'closed' });
67	                    },
68	                    configurable: true
69	                });
70	            })(node);
71	        }
72	    }
73	
74	    var p = finder.findPath(sx, sy, ex, ey, g);
75	    return { path: p, operations: ops, openedCount: ops.filter(function(o) { return o.attr === 'opened'; }).length };
76	}
